class KthLargest {
    int k;
    priority_queue<int,vector<int>,greater<int>> heap;
    public:KthLargest(int k,vector<int>& nums):k(k){
        for(int value:nums)add(value);
    }
    int add(int val){
        heap.push(val);
        if((int)heap.size()>k)heap.pop();
        return heap.top();
    }
};
